 Blob read(){std::string line;char c;DWORD n=0;while(ReadFile(output,&c,1,&n,nullptr)&&n){if(c=='\n')break;if(c!='\r')line+=c;need(line.size()<=140000,"Host response framing bound");}need(!line.empty(),"Host closed before response");return rpc::unbase64(line,100000,false);}
