static V row(Host& host,ApplicationPeer& endpoint,const std::string& local,const std::string& id){auto snapshot=host.project(endpoint.application->command(0,local,"",L""));for(const auto& item:snapshot.at("items").array)if(item.string("id")==id)return item;return V();}
static void healthy(const V& value){if(value.kind==0)return;auto state=value.string("state");if(state=="paused"||state=="failed"||state=="expired")throw std::runtime_error("Application stopped: "+rpc::json(value));}
